// Pegamos o que veio do banco (agora a coluna se chama 'numero')
const numeroBanco = $json.numero;

// Também pegamos os dados do cliente para que fluam até o AI Agent
const dadosWaha = $('Estruturar Dados WAHA').first().json;

return {
  pausado: !!numeroBanco, // Retorna true se o número existe no banco, false se não
  sessao: dadosWaha.sessao,
  telefone_real: dadosWaha.telefone_real,
  chat_id: dadosWaha.chat_id,
  mensagem: dadosWaha.mensagem,
  nome_cliente: dadosWaha.nome_cliente
};

// 1. Pegamos as variáveis de identificação que sempre rodam
let waha = {};
try {
    waha = $('Estruturar Dados WAHA').first().json;
} catch(e) {
    waha = {};
}

// 2. Pega a Transcrição do Whisper (se houver áudio)
let whisperTranscription = "";
try {
    const whisperNode = $('Transcrever').all();
    if (whisperNode.length > 0) {
        whisperTranscription = whisperNode[0].json.text || whisperNode[0].json.data || "";
    }
} catch (e) {
    whisperTranscription = "";
}

// 3. Verifica se é Áudio diretamente no Webhook
let isAudio = false;
try {
    const mime = $('Webhook').first().json.body?.payload?.media?.mimetype || "";
    isAudio = mime.includes('audio'); 
} catch(e) {}

// 4. Pega o Texto diretamente do Webhook (100% à prova de falhas)
let textoOriginal = "";
try {
    // Tenta pegar da fonte original primeiro, se falhar tenta da variável estruturada
    textoOriginal = $('Webhook').first().json.body?.payload?.body || waha.mensagem || "";
} catch (e) {}

// 5. Lógica de Roteamento Afiada: É Áudio ou Texto?
let textoFinal = "";

if (isAudio) {
    textoFinal = whisperTranscription;
} else {
    // Se não for áudio, pega o texto que o cliente digitou ("tem vaga hoje?")
    textoFinal = textoOriginal; 
}

// Limpeza final para remover espaços em branco invisíveis
textoFinal = String(textoFinal || "").trim();

// 6. Gatilho de segurança
const audioFalhou = isAudio && textoFinal === "";

// 7. Retorna o pacote completo para o Cirilo
return [{
  json: {
    mensagem: textoFinal,
    audio_falhou: audioFalhou,
    is_audio: isAudio,
    nome_cliente: waha.nome_cliente,
    telefone_real: waha.telefone_real,
    from_me: waha.from_me,
    event: waha.event,
    sessao: waha.sessao,
    chat_id: waha.chat_id,
    message_id: waha.message_id,
    id_resposta: waha.id_resposta
  }
}];

let output = $input.first().json.output || '';

  const linhas = output.split('\n');

  const limpas = linhas.filter(function(linha) {
    var l = linha.trim();
    if (l === '') return true;
    // Remove chamadas de ferramenta: to=functions.xxx
    if (/^to=functions\./i.test(l)) return false;
    // Remove linhas que são JSON puro: {"..."}
    if (/^\{.*\}$/.test(l)) return false;
    // Remove linhas com spam asiático/cirílico (3+ chars seguidos)
    if (/[\u4e00-\u9fff\u0e00-\u0e7f\u0400-\u04ff]{3,}/.test(l)) return false;
    return true;
  });

  const texto = limpas.join('\n').trim();

  return [{ json: { output: texto } }];

const TZ = 'America/Sao_Paulo';

const SERVICES = [
  { name: 'Corte',            min: 40 },
  { name: 'Barba',            min: 20 },
  { name: 'Sobrancelha',      min: 20 },
  { name: 'Corte+Barba',      min: 60 },
  { name: 'Pezinho',          min: 20 },
  { name: 'Relaxamento',      min: 40 },
  { name: 'Corte pigmentado', min: 60 }
];

// Horário de funcionamento: 0=Dom(fechado),1-5=Seg-Sex,6=Sab
const WORK = {
  1: [8*60, 19*60], 2: [8*60, 19*60], 3: [8*60, 19*60],
  4: [8*60, 19*60], 5: [8*60, 19*60], 6: [7*60, 17*60]
};

function spParts(date) {
  const f = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, year:'numeric', month:'2-digit', day:'2-digit',
    hour:'2-digit', minute:'2-digit', weekday:'short', hour12: false
  }).formatToParts(date).reduce((a,p) => { a[p.type] = p.value; return a; }, {});
  const wd = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(f.weekday);
  return {
    wd,
    key: `${f.year}-${f.month}-${f.day}`,
    label: `${f.day}/${f.month}`,
    mins: parseInt(f.hour) * 60 + parseInt(f.minute)
  };
}

function hhmm(m) {
  return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
}

const now    = new Date();
const items  = $input.first().json.items || [];
const events = items.filter(e => e && e.start);

// Agrupar eventos ocupados por dia (em minutos SP)
const occupied = {};
for (const ev of events) {
  const s   = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00');
  const e   = new Date(ev.end.dateTime   || ev.end.date   + 'T00:00:00');
  const sp  = spParts(s);
  const sep = spParts(e);
  if (!occupied[sp.key]) occupied[sp.key] = [];
  occupied[sp.key].push({ s: sp.mins, e: sep.mins });
}

const blocks = [];

// Ajustado para calcular 6 dias no total (Hoje + 5)
for (let offset = 0; offset <= 5; offset++) {
  const date = new Date(now);
  date.setDate(date.getDate() + offset);
  const sp = spParts(date);
  const wh = WORK[sp.wd];

  if (!wh) continue; // Pula os domingos automaticamente

  const [wStart, wEnd] = wh;
  let minStart = wStart;

  if (offset === 0) {
    // hoje: próximo slot de 20min após agora + 10min margem
    minStart = Math.max(wStart, Math.ceil((sp.mins + 10) / 20) * 20);
  }

  const occ = occupied[sp.key] || [];

  // Lógica para nomear os dias da semana corretamente
  let label = '';
  if (offset === 0) {
    label = `HOJE (${sp.label})`;
  } else if (offset === 1) {
    label = `AMANHÃ (${sp.label})`;
  } else {
    const diasSemana = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];
    label = `${diasSemana[sp.wd]} (${sp.label})`;
  }

  const lines = [];

  for (const svc of SERVICES) {
    const slots = [];
    for (let t = minStart; t + svc.min <= wEnd; t += 20) {
      if (!occ.some(o => t < o.e && (t + svc.min) > o.s)) {
        slots.push(hhmm(t));
      }
    }
    lines.push(`  ${svc.name} (${svc.min}min): ${slots.length ? slots.join(', ') : 'SEM DISPONIBILIDADE'}`);
  }

  blocks.push(`${label}:\n${lines.join('\n')}`);
}

return [{ json: { agenda_formatada: blocks.join('\n\n') || 'Sem horários disponíveis.' } }];

